import React, { useEffect, useState } from 'react';

export const Home = ({ data, onRouteChange }) => {
    const isMobile = useCheckMobileScreen();

    useEffect(() => {
        if (isMobile) {
            document.getElementById('home').style.paddingTop = '26vh';
        } else {
            document.getElementById('home').style.paddingTop = '';
        }
    }, [isMobile]);

    console.log(isMobile);

    return (
        <>
            <p id='title'>Mercatoria Fishing Club</p>
            <br />
            {data?.length > 0 &&
                data.map((exhibit, index) => (
                    <ExhibitThumb key={index} exhibit={exhibit} index={index} onRouteChange={onRouteChange} last={index + 1 === data.length ? true : false} />
                ))
            }
        </>
    )
}

const ExhibitThumb = ({ exhibit, index, onRouteChange, last }) => {
    const handleClick = () => {
        if (exhibit.copy_text && exhibit.copy_text != '') {
            window.scrollTo(0, 0);
            onRouteChange(`${exhibit.id}`, { state: { exhibit } });
        }
    };

    return (
        <p className='exhibit' style={last ? { margin: 0 } : { margin: '100px 0' }} onClick={handleClick}>{index + 1}.<br />
            {exhibit.first_artist} + {exhibit.second_artist}<br />
            <span className='italic'>{exhibit.title_of_exhibition}</span><br />
            {exhibit.date}<br />
        </p>
    )
}

const useCheckMobileScreen = () => {
    const [width, setWidth] = useState(window.innerWidth);
    const handleWindowSizeChange = () => {
        setWidth(window.innerWidth);
    }

    useEffect(() => {
        window.addEventListener('resize', handleWindowSizeChange);
        return () => {
            window.removeEventListener('resize', handleWindowSizeChange);
        }
    }, []);

    return (width <= 768);
}