import MarkdownView from 'react-showdown';
import React, { useEffect } from 'react';
import { useLocation, Link } from 'react-router-dom';

const applyIndentation = () => {
    document.querySelectorAll('#exhibitText p').forEach((p) => {
        if (p.querySelector('em') && p.innerHTML.trim().startsWith('<em>') && p.innerHTML.trim().endsWith('</em>')) {
            p.style.marginLeft = '10px';
        } else {
            p.style.textIndent = '20px';
        }
    });
};

export const Exhibit = () => {
    const location = useLocation();
    const { exhibit } = location.state.state || {};

    useEffect(() => {
        document.getElementById('home').style.paddingTop = '0'
    }, []);

    useEffect(() => {
        applyIndentation();
    }, [exhibit.copy_text]);

    return (
        <>
            <div id='exhibitGeneralText'>
                <Link to="/" onClick={() => { window.scrollTo(0, 0); }} id='backButton'><p>Back</p></Link>
                <h2>{exhibit.first_artist} + {exhibit.second_artist}</h2>
                <h1 >{exhibit.title_of_exhibition}</h1>
                <h2 style={{ marginBottom: 50 }}>{exhibit.date}</h2>
                <MarkdownView markdown={exhibit.copy_text || ''} options={{ tables: true, emoji: true }} />
            </div>
            <div id='Artists'>
                <div id='exhibitFirstArtist' className='artistContent'>
                    <h2>{exhibit.first_artist}</h2>
                    <MarkdownView markdown={exhibit.copy_text_first_artist || ''} options={{ tables: true, emoji: true }} />
                    {exhibit?.images_of_first_artist.map((url, index) => (
                        <img key={index} className='artistImages' src={url} />
                    ))}
                </div>
                <div id='exhibitSecondArtist' className='artistContent'>
                    <h2>{exhibit.second_artist}</h2>
                    <MarkdownView markdown={exhibit.copy_text_second_artist || ''} options={{ tables: true, emoji: true }} />
                    {exhibit?.images_of_second_artist.map((url, index) => (
                        <img key={index} className='artistImages' src={url} />
                    ))}
                </div>
            </div>
            <div id='exhibitionImages'>
                {exhibit?.images_of_exhibition.map((url, index) => (
                    <img key={index} className='artistImages' src={url} />
                ))}
            </div>
        </>
    )
}