import React, { useState, useEffect } from 'react';
import './App.css';
import { ExhibitionData } from './Firebase.js'
import { Home } from './pages/Home.js'
import { Exhibit } from './pages/Exhibit.js'
import { Route, Routes, useNavigate } from "react-router-dom"

function App() {
  const [exhibitionData, setExhibitionData] = useState([]);
  const [routeChanging, setRouteChanging] = useState(false);

  const navigate = useNavigate();

  const fetchData = async () => {
    const fetchedExhibitionData = await ExhibitionData();
    setExhibitionData([...fetchedExhibitionData]);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleRouteChange = (path, state = {}) => {
    setRouteChanging(true);
    navigate(path, { state });
  };

  useEffect(() => {
    if (routeChanging) {
      setRouteChanging(false);
    }
  }, [routeChanging]);

  return (
    <div className="App">
      <div id='home'>
        <div id='fish-overlay'></div>
        <Routes>
          <Route
            path="/"
            element={<Home data={exhibitionData} onRouteChange={handleRouteChange} />}
          />
          <Route path="/:id" element={<Exhibit />} />
        </Routes>
      </div>
    </div>
  );
}

export default App;
