// Initialize Firebase

const app = initializeApp(firebaseConfig);

const db = getFirestore(app);

export const ExhibitionData = async () => {
    //Get exhibitions data
    const exhibitions = [];
    await getDocs(collection(db, "exhibitions"))
        .then((querySnapshot) => {
            querySnapshot.forEach(exhibition => {
                exhibitions.push({
                    id: exhibition.id,
                    ...exhibition.data()
                })
            });
        });

    return exhibitions;
};